            ['status' => 'open', 'title' => 'Schnelle Meldung am Handy', 'note' => 'Für Leitende ohne Zeit: „Gruppenstunde fällt aus“ oder ein kurzer Beitrag mit Foto in unter fünf Minuten, ohne das volle Backend. Ein Teil davon ist schon möglich, wenn nicht benötigte Funktionen abgeschaltet sind.'],
            ['status' => 'open', 'title' => 'Termine von Bezirk und Diözesanverband übernehmen', 'note' => 'Auf der eigenen Seite Termine aus Bezirk und DV einblenden (Abo, siehe Meilenstein Bezirke) – die Stammesseite bleibt eigenständig, verpasst aber nichts.'],
            ['status' => 'later', 'title' => 'Zelt- und Materialverleih, Belegung des Stammesheims', 'note' => 'Liste mit Material, Anfrage und Kalender der Belegung.'],
            ['status' => 'later', 'title' => 'Lagerfotos nur für Eltern', 'note' => 'Galerie, die nur mit Code öffnet (Prinzip wie „Meine Anmeldungen“); nur mit Einwilligung zu Fotos.'],
            ['status' => 'done', 'title' => 'Veranstaltungen nur für Mitglieder der eigenen Gruppierung', 'note' => 'Je Veranstaltung „Nur für Mitglieder von …“ (Stamm oder Bezirk mit allen Stämmen). Die Seite weist darauf hin; der Mitgliederabgleich mit NaMi markiert jede Anmeldung als „eigene Gruppierung“ oder „andere Gruppierung“ – über die DPSG-Nummer der Gruppierung (z. B. 21-01-08), sonst über die Karte. Filter und Exportspalte „Eigene Gruppierung“. Niemand wird automatisch abgelehnt; Gäste gelten als „andere“. Gilt die Mitgliedschaft (Stammgruppierung), nicht weitere Tätigkeiten.'],
            ['status' => 'open', 'title' => 'Erster echter Abgleich: Format der Gruppierung in NaMi prüfen', 'note' => 'Steht die DPSG-Nummer in der NaMi-Gruppierungsbezeichnung (z. B. „… 210108“)? Sonst greift nur der Namensvergleich mit der Karte. Mit dem eigenen NaMi-Zugang an einer Testveranstaltung prüfen.'],
            ['status' => 'decide', 'title' => 'Mitglieder anderer Gruppierungen automatisch auf die Warteliste?', 'note' => 'Heute nur Markierung, die Leitung entscheidet. Möglich: Anmeldungen „andere Gruppierung“ nach dem Abgleich automatisch auf die Warteliste setzen und die Leitung benachrichtigen. Aufwand: klein.'],
        ],
        'Testing' => [
            ['status' => 'done', 'title' => 'Protokoll im Backend lesen', 'note' => 'Verwaltung → Protokoll (nur Admins): das Audit-Log als Liste mit Zeitpunkt, Person, verständlichem Text (z. B. „Funktion ausgeschaltet: Download-Seite“) und betroffenem Datensatz mit Link; Filter nach Bereich, Person und Zeitraum. Nur lesen – nichts bearbeitbar oder löschbar; Einträge verschwinden nach 12 Monaten automatisch.'],
            ['status' => 'done', 'title' => 'Funktionen im Backend an- und abschalten', 'note' => 'Verwaltung → Funktionen (nur Admins): Download-Seite, Zeitschriften-Archiv, Rechtsträger-Schaubild, Roadmap, Teilnehmende von Hand eintragen, Gäste-Kästchen, Teilnahmebescheinigung, Mitgliederabgleich, NaMi-Zugang im Profil, „Nur für Mitglieder von …“, Push-Nachrichten, WordPress-Import. Standard je Website aus der Instanz-Konfiguration; abgeschaltete Funktionen verschwinden aus Website und Backend, Daten bleiben erhalten; jede Änderung im Protokoll.'],
            ['status' => 'done', 'title' => 'Echte Mails an ausgewählte Tester*innen', 'note' => 'Auf test.dpsg-trier.de gehen alle Mails an die Testadresse – außer an bis zu zehn freigeschaltete Adressen (GitHub-Secret MAIL_TEST_ALLOWLIST); diese Empfänger*innen bekommen ihre Bestätigungen, Antworten usw. direkt. Die Testadresse sieht im Mail-Kopf „X-Test-Umgeleitet-Von“, an wen eine umgeleitete Mail gegangen wäre. Mit dem Livegang entfallen Umleitung und Ausnahmen.'],
        ],
        'Talia' => [
            ['status' => 'open', 'title' => 'Aktuelles weiter nach vorne', 'note' => 'Empfehlung: im Menü direkt hinter „Start“ und auf der Startseite die Meldungen vor den Begrüßungstext. Funktioniert nur, wenn regelmäßig neue Beiträge kommen – sonst steht ganz oben Veraltetes.'],
            ['status' => 'open', 'title' => 'Suche', 'note' => 'Im Pflichtenheft als Soll vorgesehen (F-CMS-07). Empfehlung: einfache Suche über Seiten, Beiträge, Veranstaltungen und Stämme jetzt bauen (Lupe im Kopf); mit MariaDB jetzt auch als Volltextsuche mit sinnvoller Trefferreihenfolge möglich.'],
            ['status' => 'done', 'title' => 'Footer ohne Wiederholung des Menüs', 'note' => 'Umgesetzt: Footer nur noch mit Kontakt, Service, „DPSG im Netz“ und Georgsbrief-Anmeldung.'],
            ['status' => 'partial', 'title' => 'Meine Anmeldungen (E-Mail + Einmalcode)', 'note' => 'Umgesetzt: /meine-anmeldungen – ohne Konto, nur E-Mail und sechsstelliger Code (10 Minuten, 5 Versuche, danach 1 Stunde freigeschaltet). Übersicht aller Anmeldungen zur Adresse (auch für Kinder oder Gruppen), selbst stornieren, Dokumente herunterladen. Das Diözesanbüro lädt Rechnungen, Bescheinigungen oder sonstige PDFs je Anmeldung hoch (Teilnehmende → Dokumente), auf Wunsch mit Hinweis-Mail; eine neue Bescheinigung ersetzt die alte. Dateien liegen nicht öffentlich und werden mit der Anmeldung gelöscht. Offen: automatisch erzeugte Teilnahmebescheinigung mit Prüfcode, längere Aufbewahrung (Dauer klären).'],
            ['status' => 'open', 'title' => 'Weniger Beige', 'note' => 'Die Farben sind die des DPSG-CD (Leitfaden April 2026); Beige ist dort für Flächen und Fußzeile vorgesehen, aber kein Muss. Empfehlung: Footer in DPSG-Blau, Infoboxen hellgrau/weiß, Beige nur noch sparsam.'],
            ['status' => 'done', 'title' => 'Diözesan-Logo größer', 'note' => 'Umgesetzt: Logo im Kopf 1,4-fach (Desktop). Für noch größer und gestochen scharf: Logo als SVG/PDF aus dem Diözesanbüro.'],
            ['status' => 'done', 'title' => 'Anmeldung bestätigen: doppelter Klick', 'note' => 'Behoben: Nach dem Klick auf „Anmeldung bestätigen“ in der Mail wird die Anmeldung sofort bestätigt, ohne zweiten Klick auf der Website. Linkscanner in Mailprogrammen (z. B. Outlook) lösen weiterhin keine Bestätigung aus, weil die Seite nur im Browser mit JavaScript automatisch absendet. Stornieren fragt bewusst noch einmal nach.'],
            ['status' => 'done', 'title' => 'Mobiles Menü: nicht alle Punkte erreichbar', 'note' => 'Behoben: Das Menü auf dem Handy ist länger als der Bildschirm und ließ sich nicht scrollen – Veranstaltungen, Kalender und Aktuelles waren nicht erreichbar. Jetzt scrollt das Menü selbst, die Seite dahinter bleibt stehen.'],
            ['status' => 'done', 'title' => 'Inklusions-Lilie für den Fachbereich Inklusion', 'note' => 'Umgesetzt: Inklusions-Lilie von dpsg.de (für die Arbeit in der DPSG frei verfügbar) im Kopf der Inklusionsseite und auf der Fachbereichsübersicht.'],
        ],
        'Lisa' => [
            ['status' => 'done', 'title' => 'Fachbereiche Spiritualität, Ausbildung und Ökologie', 'note' => 'Je eine Seite unter „Fachbereiche“ mit Menüpunkt, eigener Farbe, Starttext und Thema im Kontaktformular (/spiritualitaet, /ausbildung, /oekologie). Auf bestehenden Installationen legt eine Inhalts-Migration der Instanz die Seiten an, ohne Vorhandenes zu überschreiben.'],
            ['status' => 'done', 'title' => 'Facharbeitskreis (FAK) je Fachbereich', 'note' => 'Neues Gremium „Facharbeitskreis (FAK)“ in der Personenverwaltung: Mitglieder erscheinen auf der Seite ihres Fachbereichs im Abschnitt „Der Facharbeitskreis“, ohne eigene Adresse und getrennt von den Ansprechpersonen, mit Hinweis zum Mitmachen – wie der DAK bei den Stufen.'],
            ['status' => 'open', 'title' => 'Starttexte der drei Fachbereiche prüfen', 'note' => 'Die Seiten haben allgemeine Starttexte. Bitte von den Fachbereichen Spiritualität, Ausbildung und Ökologie prüfen und ergänzen lassen (Backend → Seiten).'],
            ['status' => 'open', 'title' => 'Referent*innen und FAK-Mitglieder eintragen', 'note' => 'Backend → Personen: Referent*innen mit „Ansprechperson für Fachbereich“, Ehrenamtliche mit Gremium „Facharbeitskreis (FAK)“ und Fachbereich. Nur mit Einwilligung der Personen.'],
            ['status' => 'open', 'title' => 'Farben für Spiritualität und Ausbildung abstimmen', 'note' => 'Im DPSG-CD sind dafür keine Fachbereichsfarben festgelegt. Vorläufig: dunkles Cyan (Spiritualität) und DPSG-Blau (Ausbildung); Ökologie im vorhandenen Grün, das auch BeratungsPower nutzt.'],
            ['status' => 'done', 'title' => 'Diözesanbüro unten bei „Diözesanverband“', 'note' => 'Das Diözesanbüro erscheint zusätzlich als Kachel unten auf der Seite „Diözesanverband“; es bleibt Unterseite von „Kontakt“ und ist weiter oben in der Servicezeile verlinkt.'],
            ['status' => 'done', 'title' => 'Test: Anmeldung und Stornieren', 'note' => 'Von Lisa ausprobiert: Anmeldung zu einer Veranstaltung und Stornieren über „Meine Anmeldungen“ funktionieren.'],
            ['status' => 'done', 'title' => 'Cartoon: „BP“ statt „PB“', 'note' => 'Auf dem ersten Cartoon unter „Stöbern & Schmökern“ stand „PB BeratungsPower & Coaching“. Bild und Alternativtext korrigiert; auf der laufenden Seite mit dem nächsten Deploy.'],
            ['status' => 'open', 'title' => 'Frage an die Kontaktperson kam nicht an', 'note' => 'Sehr wahrscheinlich kein Fehler: In der Testphase gehen alle Mails an die Testadresse, außer an freigeschaltete Tester*innen. Lisas Adresse in MAIL_TEST_ALLOWLIST aufnehmen (GitHub-Environment, höchstens zehn Einträge), dann noch einmal testen. Die umgeleitete Mail müsste im Postfach der Testadresse liegen.'],
            ['status' => 'open', 'title' => 'Titel und Willkommenstext der Startseite', 'note' => 'Ohne Programmierung möglich: Backend → Seiten → „Pfadfinden im Bistum Trier“ (Startseite). Titel = große Überschrift, SEO-Beschreibung = Unterzeile, Inhalt = Willkommenstext.'],
            ['status' => 'decide', 'title' => 'Eigene Seite für Divers', 'note' => 'Heute: Einladung als Beitrag mit Veranstaltung. Möglich wäre eine eigene Seite (z. B. unter „Diözesanverband“ oder „Fachbereiche“), auf die Beitrag und Veranstaltung verweisen. Aufwand: klein, vor allem Text.'],
            ['status' => 'decide', 'title' => 'Übernachtungs-Auswahl je Veranstaltung anpassen', 'note' => 'Heute gibt es für alle Veranstaltungen dieselben drei Antworten (ganze Zeit, teilweise, ohne); einzelne Tage gehen über „Anwesenheit (Tage)“. Möglich: eigene Antworten je Veranstaltung im Backend. Aufwand: klein bis mittel.'],
            ['status' => 'done', 'title' => 'PLZ und Wohnort für LJR-Anträge', 'note' => 'Zwei neue Felder im Baukasten der Anmeldung (Postleitzahl, Wohnort), je Veranstaltung „optional“ oder „Pflichtfeld“; auch 4-stellige PLZ aus Luxemburg und Belgien. Erscheinen in der Teilnehmendenliste und im Export. Teilnehmendenlisten für Zuschüsse verlangen meist Name, Anschrift und Alter (Geburtsjahr gibt es schon als Feld) sowie die Unterschrift vor Ort; ob der Landesjugendring Saar mehr braucht (z. B. Straße), bitte dort nachfragen.'],
            ['status' => 'decide', 'title' => 'Kalender und Veranstaltungen zusammenführen', 'note' => 'Heute: „Veranstaltungen“ sind eigene Termine mit Seite und Anmeldung, der „Kalender“ zeigt die Termine aus Nextcloud (nur Titel, Zeit, Ort). Möglich: eine gemeinsame Terminliste, Veranstaltungen mit Anmeldung hervorgehoben; Kalendertermine mit Beschreibung und Link aus Nextcloud. Aufwand: mittel.'],
            ['status' => 'done', 'title' => 'Cartoons bei BeratungsPower kleiner', 'note' => 'Stehen in einem Text drei oder mehr Bilder direkt hintereinander, zeigt die Seite sie jetzt als Galerie: klein nebeneinander, ein Klick öffnet das Bild in voller Größe. Gilt für alle Seiten und Beiträge, einzelne Bilder bleiben groß.'],
            ['status' => 'done', 'title' => 'Stufen: auch AK-Mitglieder bei „Melde dich gern bei …“', 'note' => 'Im Satz „Lust, im DAK … mitzuarbeiten? Melde dich gern bei …“ stehen jetzt neben den Referent*innen (mit Mail-Link) auch die Mitglieder des Arbeitskreises; ihr Name springt zu ihrer Karte auf der Seite, eine Mailadresse wird weiter nicht veröffentlicht. Genauso beim FAK auf den Fachbereichsseiten.'],
            ['status' => 'decide', 'title' => 'Eine Anmeldung für mehrere Termine (z. B. alle Ausbildungswochenenden)', 'note' => 'Wahlweise alle Termine einer Reihe auf einmal oder einzeln buchen. Braucht eine Veranstaltungsreihe im Backend, Plätze und Wartelisten je Termin, Stornieren einzeln oder gesamt. Aufwand: groß.'],
            ['status' => 'done', 'title' => 'Bereich Prävention', 'note' => 'Eigene Seite unter „Diözesanverband“ (/praevention), als Thema der Hauptberuflichen ohne Facharbeitskreis: Haltung, Schutzkonzept, Präventionsschulung, erweitertes Führungszeugnis, Verhaltenskodex und Hilfe bei Verdacht (Ansprechpersonen und Fachstelle des Bistums Trier, Hilfetelefon, Nummer gegen Kummer, Aufarbeitung der DPSG). Axel Hemgesberg erscheint als Ansprechperson; Thema „Prävention und Schutz“ im Kontaktformular; Downloads mit dem Fachbereich „Prävention“ erscheinen automatisch als Dokumente auf der Seite.'],
            ['status' => 'open', 'title' => 'Präventionsseite mit Axel abstimmen', 'note' => 'Starttext prüfen (Schutzkonzept, Schulungen, Führungszeugnis, Verhaltenskodex) und Dokumente hochladen: Schutzkonzept, Verhaltenskodex – im Backend unter „Downloads“ mit Fachbereich „Prävention“.'],
            ['status' => 'done', 'title' => 'Download-Seite für Methoden und Dokumente', 'note' => 'Neue Seite „Downloads“ unter „Diözesanverband“: Karten mit Dateityp, Kurzbeschreibung, Stufe oder Fachbereich und Infozeile (z. B. „12 Seiten · 1,4 MB · Stand 03/2026“), Kennzeichen „neu“, Suche und Filter nach Kategorie. Gepflegt im Backend unter „Downloads“ (Verwaltung); Typ, Größe, Seiten und Stand ermittelt das CMS. Kategorien: Abrechnungen, Zuschüsse & Förderung, Formulare, Methoden, Arbeitshilfen, Prävention. Funktion für alle Kluft-Gliederungen.'],
            ['status' => 'done', 'title' => 'Abrechnungsformulare für die Diözesanebene', 'note' => 'Fahrt-, Reise- und Sachkostenabrechnung von der bisherigen Seite „Service → Formulare“ übernommen; die alte Adresse leitet auf die Download-Seite. Die neue Fahrtkostenabrechnung 2026 ist am PC ausfüllbar, rechnet Kilometer und Betrag (0,30 € pro km) selbst, formatiert die IBAN in Vierergruppen und warnt bei Tippfehlern (Prüfziffer).'],
            ['status' => 'done', 'title' => 'Reise- und Sachkostenabrechnung 2026', 'note' => 'Neu aufgebaut auf der Vorlage der Fahrtkostenabrechnung 2026 (neuer Briefkopf, Weberbach 71): am PC ausfüllbar, zählen die Belege, rechnen den Auszahlungsbetrag, formatieren und prüfen die IBAN. Alle drei Formulare haben jetzt eine Überschrift; die Word-Fassungen liegen mit im Repository.'],
            ['status' => 'done', 'title' => 'Fachbereich Politische Bildung', 'note' => 'Eigene Seite unter „Fachbereiche“ (/politische-bildung) mit Menüpunkt, Farbe (Violett, vorläufig), Starttext zu Vielfalt, Kinderarmut, Kinderrechten, Demokratie und „Kein Bock auf Nazis“, Facharbeitskreis und Thema im Kontaktformular. Starttext bitte prüfen.'],
            ['status' => 'done', 'title' => 'Teilnahmebescheinigung als PDF mit Prüfcode', 'note' => 'Je Veranstaltung einschaltbar (mit „Inhalte und Umfang“ und Unterzeichner*in). Die Veranstaltungsleitung gibt unter „Teilnehmende“ frei – einzeln oder für alle markierten Anmeldungen auf einmal; die Personen bekommen eine Mail und laden das PDF unter „Meine Anmeldungen“. Gestaltung nach CD (Arvo/Calibri, DPSG-Blau und -Rot, Logo). Prüfcode mit Prüfziffer und QR-Code; Echtheitsprüfung unter /bescheinigung-pruefen mit Code und Namen, ohne dafür Daten zu speichern – funktioniert auch nach Ablauf der Löschfrist. Eine hochgeladene Bescheinigung ersetzt die erzeugte.'],
            ['status' => 'done', 'title' => 'Teilnehmende von Hand eintragen, auch als Liste', 'note' => 'Unter „Teilnehmende“ → „Teilnehmende eintragen“: einzeln (für Anmeldungen per Telefon, Mail oder Papier) oder als Liste – aus Excel kopiert und eingefügt oder als .xlsx/.csv hochgeladen. Eine Kopfzeile ordnet die Spalten zu (Vorname, Nachname oder Name, E-Mail, Geburtsjahr und die Felder der Veranstaltung wie PLZ, Wohnort, Stamm). Ohne Double-Opt-In, bestätigt solange Plätze frei sind, danach Warteliste (oder fest gewählt); E-Mail optional, Bestätigungsmail auf Wunsch. Wer schon angemeldet ist, wird übersprungen; fehlerhafte Zeilen werden gemeldet. Jede Eintragung steht im Protokoll.'],
            ['status' => 'done', 'title' => 'Gäste aus anderen Diözesanverbänden und Verbänden', 'note' => 'Unter „Stamm / Bezirk / Verband“ gibt es das Ankreuzfeld „Gast aus einem anderen Diözesanverband oder Verband“; dann bitte Verband und Gruppe eintragen (z. B. „DV Köln, Stamm …“ oder „VCP …“). Gäste stehen in Liste und Export mit „Herkunft“ und werden beim Mitgliederabgleich nicht abgefragt, sondern als „Gast“ markiert (statt „nicht gefunden“). Auch beim Eintragen von Hand und in Listen (Spalte „Gast“: ja).'],
            ['status' => 'done', 'title' => 'Mitgliedsnummer und Stamm aus NaMi', 'note' => 'Ein Feld „Stamm / Bezirk / Verband“ mit Vorschlägen für Stämme und Bezirke (manche melden sich als Stamm, andere als Bezirk an). Die Mitgliedsnummer kommt nur aus NaMi: Einmal zugeordnet, ordnet sie bei jedem weiteren Abgleich eindeutig zu, auch bei Namensgleichheit und bei von Hand eingetragenen Teilnehmenden ohne E-Mail. Ist das Feld leer, übernimmt der Abgleich Stamm bzw. Bezirk aus NaMi (über die DPSG-Nummer der Gruppierung). Einwilligungstext und Datenschutzauskunft sind angepasst.'],
